@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryDisplay Recipes - RecipeShare</PageTitle>

<h1>@CategoryDisplay Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryDisplay</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipes/@Category/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe> recipes = [];

    private string CategoryDisplay => Category?.Replace("-", " ") switch
    {
        "appetizers" => "Appetizers",
        "main courses" => "Main Courses",
        "desserts" => "Desserts",
        _ => Category ?? "Recipes"
    };

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipes/{Category}/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@recipe.Title - RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@Category">@CategoryDisplay</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="@recipe.Id" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <h3>Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-8">
            <h3>Steps</h3>
            @foreach (var step in recipe.Steps.Split('\n'))
            {
                <p>@step</p>
            }
        </div>
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Parameter] public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    private string CategoryDisplay => Category?.Replace("-", " ") switch
    {
        "appetizers" => "Appetizers",
        "main courses" => "Main Courses",
        "desserts" => "Desserts",
        _ => Category ?? "Recipes"
    };

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star stars"
                disabled="@hasRated">
            @(star <= displayRating ? "★" : "☆")
        </button>
    }
    <span class="text-muted ms-2">
        @if (hasRated)
        {
            <text>Thanks! You rated @userRating star@(userRating == 1 ? "" : "s").</text>
        }
        else
        {
            <text>Click to rate</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int displayRating;
    private int userRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        if (hasRated) return;

        userRating = stars;
        displayRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@recipe.Title" has been added.
        <a href="/recipes/@recipe.Category/@recipe.Id">View it here</a>.
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="recipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="recipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => recipe.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="recipe.Category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => recipe.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="recipe.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => recipe.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="recipe.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
            <ValidationMessage For="() => recipe.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private Recipe recipe = new();
    private bool submitted;

    private void HandleSubmit()
    {
        RecipeService.Add(recipe);
        submitted = true;
    }

    private void Reset()
    {
        recipe = new();
        submitted = false;
    }
}

